#include <Arduino.h>
const int BUTTON_PIN = 2;  
int currentMode = 0;
unsigned long lastDebounceTime = 0;
bool buttonState = HIGH;  
bool lastButtonState = HIGH;  

void setup();
void loop();
void updateDisplay();
void setup() {
  pinMode(BUTTON_PIN, INPUT_PULLUP);
  for (int i = 3; i <= 8; i++) {  
    pinMode(i, OUTPUT);
  }
  for (int i = 9; i <= 13; i++) {  
    pinMode(i, OUTPUT);
  }
  pinMode(44, OUTPUT);  
  pinMode(45, OUTPUT);  
  updateDisplay();
}
void loop() {
  int reading = digitalRead(BUTTON_PIN);
  if (reading != lastButtonState) {
    lastDebounceTime = millis();  
  }
  if ((millis() - lastDebounceTime) > 50) {
    if (reading != buttonState) {
      buttonState = reading;
      if (buttonState == LOW) {
        currentMode = (currentMode + 1) % 8;
        updateDisplay();
      }
    }
  }
  lastButtonState = reading;  
}
void updateDisplay() {
  for (int i = 3; i <= 13; i++) {
    digitalWrite(i, LOW);
  }
  digitalWrite(44, LOW);
  digitalWrite(45, LOW);
  switch (currentMode) {
    case 1:
      digitalWrite(3, HIGH);  
      digitalWrite(8, HIGH);  
      digitalWrite(9, HIGH);  
      break;
    case 2:
      digitalWrite(4, HIGH);  
      digitalWrite(7, HIGH);  
      digitalWrite(8, HIGH);  
      digitalWrite(9, HIGH);  
      digitalWrite(10, HIGH);  
      break;
    case 3:
      digitalWrite(3, HIGH);  
      digitalWrite(4, HIGH);  
      digitalWrite(6, HIGH);  
      digitalWrite(8, HIGH);  
      for (int i = 9; i <= 11; i++) digitalWrite(i, HIGH);  
      break;
    case 4:
      digitalWrite(4, HIGH);  
      digitalWrite(5, HIGH);  
      digitalWrite(6, HIGH);  
      digitalWrite(7, HIGH);  
      for (int i = 9; i <= 12; i++) digitalWrite(i, HIGH);  
      break;
    case 5:
      digitalWrite(3, HIGH);  
      digitalWrite(5, HIGH);  
      digitalWrite(7, HIGH);  
      digitalWrite(8, HIGH);  
      for (int i = 9; i <= 13; i++) digitalWrite(i, HIGH);  
      break;
    case 6:
      digitalWrite(3, HIGH);  
      digitalWrite(4, HIGH);  
      digitalWrite(5, HIGH);  
      digitalWrite(6, HIGH);  
      digitalWrite(7, HIGH);  
      for (int i = 9; i <= 13; i++) digitalWrite(i, HIGH);  
      digitalWrite(44, HIGH);
      break;
    case 7:
      digitalWrite(6, HIGH);  
      digitalWrite(7, HIGH);  
      digitalWrite(8, HIGH);  
      for (int i = 9; i <= 13; i++) digitalWrite(i, HIGH);  
      digitalWrite(44, HIGH);  
      digitalWrite(45, HIGH);  
      break;
  }
}
